<script>addEventListener('DOMContentLoaded',()=>{const key='dailybreath.settings',defaults={theme:'seasonal',reduceMotion:false},t=document.getElementById('theme'),m=document.getElementById('motion'),button=document.getElementById('save-settings');let settings=defaults;try{const stored=JSON.parse(localStorage.getItem(key)||'{}');if(stored&&typeof stored==='object')settings={...defaults,...stored}}catch(error){localStorage.removeItem(key)}t.value=['seasonal','fall','system','dawn','dusk'].includes(settings.theme)?settings.theme:defaults.theme;m.checked=!!settings.reduceMotion;const save=()=>{settings={...settings,theme:t.value,reduceMotion:m.checked};localStorage.setItem(key,JSON.stringify(settings));if(window.DailyBreath)DailyBreath.settings=settings;if(window.DailyBreath?.toast)DailyBreath.toast('Settings saved.');setTimeout(()=>location.reload(),300)};button.addEventListener('click',save);t.addEventListener('change',save);m.addEventListener('change',save);document.querySelectorAll('[data-art-choice]').forEach(card=>card.addEventListener('click',()=>{const tradition=card.dataset.artChoice,theme=tradition==='quran'?'dusk':'dawn';settings={...settings,theme,reduceMotion:m.checked};localStorage.setItem(key,JSON.stringify(settings));localStorage.setItem('dailybreath.tradition',tradition);document.cookie='dailybreath_faith='+tradition+'; Max-Age=31536000; Path=/dailybreath/; SameSite=Lax';location.href='index.php?faith='+encodeURIComponent(tradition)+'&artwork=1'}))})</script><?= dailybreath_web_scripts() ?><script src="/assets/js/visitor-analytics.js" defer></script></body></html>
